(function(){
  var berries = [
    {cx:0.74,cy:0.07,r:0.042,ph:0.1},
    {cx:0.80,cy:0.05,r:0.042,ph:0.5},
    {cx:0.86,cy:0.07,r:0.040,ph:0.9},
    {cx:0.70,cy:0.12,r:0.045,ph:1.3},
    {cx:0.77,cy:0.11,r:0.046,ph:1.7},
    {cx:0.83,cy:0.12,r:0.045,ph:2.1},
    {cx:0.89,cy:0.13,r:0.043,ph:2.5},
    {cx:0.68,cy:0.17,r:0.043,ph:2.9},
    {cx:0.74,cy:0.17,r:0.044,ph:3.3},
    {cx:0.80,cy:0.18,r:0.043,ph:3.7},
    {cx:0.86,cy:0.18,r:0.041,ph:4.1},
    {cx:0.70,cy:0.23,r:0.038,ph:4.5},
    {cx:0.76,cy:0.24,r:0.039,ph:4.9},
    {cx:0.82,cy:0.24,r:0.037,ph:5.3},
    {cx:0.72,cy:0.29,r:0.033,ph:5.7},
    {cx:0.78,cy:0.30,r:0.032,ph:6.1},
    {cx:0.75,cy:0.35,r:0.028,ph:6.5}
  ];

  var fog = [];
  var fogCount = 70;
  for(var i=0;i<fogCount;i++){
    fog.push({
      x: Math.random(),
      y: 0.55 + Math.random()*0.5,
      r: 0.6 + Math.random()*1.8,
      sp: 0.03 + Math.random()*0.07,
      ph: Math.random()*Math.PI*2,
      sway: (Math.random()-0.5)*0.0008
    });
  }

  var t = 0;

  function draw(){
    var w = W(), h = H();
    ctx.clearRect(0,0,w,h);
    t += 0.012;
    var m = Math.min(w,h);

    // ambient warm glow behind cluster
    ctx.save();
    var ag = ctx.createRadialGradient(w*0.80,h*0.15,0,w*0.80,h*0.15,m*0.32);
    ag.addColorStop(0, PALETTE[1]+'33');
    ag.addColorStop(1, PALETTE[1]+'00');
    ctx.fillStyle = ag;
    ctx.fillRect(0,0,w,h);
    ctx.restore();

    // stem
    ctx.save();
    ctx.strokeStyle = PALETTE[1];
    ctx.globalAlpha = 0.45;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(w*0.84, -10);
    ctx.quadraticCurveTo(w*0.78, h*0.03, w*0.76, h*0.065);
    ctx.stroke();

    // tendril spiral
    ctx.beginPath();
    var tx = w*0.88, ty = h*0.015;
    for(var a=0; a<Math.PI*3.2; a+=0.2){
      var rr = (0.018 - a*0.0022) * m;
      if(rr<0) break;
      var px = tx + Math.cos(a+t*0.2)*rr;
      var py = ty + Math.sin(a+t*0.2)*rr + a*2;
      if(a===0){ ctx.moveTo(px,py); } else { ctx.lineTo(px,py); }
    }
    ctx.globalAlpha = 0.35;
    ctx.stroke();
    ctx.restore();

    // berries
    berries.forEach(function(b){
      var bx = w*b.cx + Math.sin(t*0.3+b.ph)*1.5;
      var by = h*b.cy + Math.cos(t*0.25+b.ph)*1.5;
      var r = b.r * m;

      var grad = ctx.createRadialGradient(bx-r*0.35, by-r*0.35, r*0.08, bx, by, r);
      grad.addColorStop(0, PALETTE[1]+'dd');
      grad.addColorStop(0.55, PALETTE[0]+'ee');
      grad.addColorStop(1, PALETTE[0]+'44');

      ctx.save();
      ctx.shadowColor = PALETTE[1];
      ctx.shadowBlur = 10 + 6*Math.sin(t*0.6+b.ph);
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.ellipse(bx, by, r, r*1.06, 0, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();

      ctx.save();
      ctx.globalAlpha = 0.22 + 0.08*Math.sin(t*0.8+b.ph);
      ctx.fillStyle = PALETTE[2];
      ctx.beginPath();
      ctx.ellipse(bx - r*0.32, by - r*0.38, r*0.26, r*0.17, -0.5, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
    });

    // slow settling frost particles, lower region, avoiding center
    fog.forEach(function(p){
      p.y += p.sp*0.0015;
      p.x += p.sway;
      if(p.y > 1.08){ p.y = 0.55; p.x = Math.random(); }
      if(p.x<-0.05) p.x = 1.05;
      if(p.x>1.05) p.x = -0.05;

      var px = p.x*w, py = p.y*h;
      var alpha = 0.10 + 0.12*Math.sin(t*1.4+p.ph);
      ctx.save();
      ctx.globalAlpha = Math.max(0, alpha);
      ctx.fillStyle = PALETTE[2];
      ctx.beginPath();
      ctx.arc(px, py, p.r, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
    });

    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
